() => {
  return new Promise(async (resolve) => {
    const header = document.querySelector('header');
    const hRect = header.getBoundingClientRect();
    const W = Math.round(hRect.width), H = Math.round(hRect.height);
    const SCALE = 2;
    const canvas = document.createElement('canvas');
    canvas.width = W * SCALE; canvas.height = H * SCALE;
    const ctx = canvas.getContext('2d');
    ctx.scale(SCALE, SCALE);
    const iconJobs = [];
    function drawBg(el, x, y, w, h) {
      const cs = getComputedStyle(el);
      const bg = cs.backgroundColor;
      const radius = parseFloat(cs.borderTopLeftRadius) || 0;
      const bw = parseFloat(cs.borderTopWidth) || 0;
      const bc = cs.borderTopColor;
      const hasBg = bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent';
      const hasBorder = bw > 0 && bc && bc !== 'rgba(0, 0, 0, 0)';
      let gradientFill = null;
      const bgImg = cs.backgroundImage;
      if (bgImg && bgImg.includes('linear-gradient')) {
        const m = bgImg.match(/rgb\([^)]+\)|#[0-9a-fA-F]{3,8}/g);
        if (m && m.length >= 2) { const g = ctx.createLinearGradient(x + w, y + h, x, y); g.addColorStop(0, m[0]); g.addColorStop(1, m[m.length - 1]); gradientFill = g; }
      }
      if (!hasBg && !hasBorder && !gradientFill) return;
      ctx.beginPath();
      if (radius > 0 && ctx.roundRect) ctx.roundRect(x, y, w, h, radius); else ctx.rect(x, y, w, h);
      if (gradientFill) { ctx.fillStyle = gradientFill; ctx.fill(); } else if (hasBg) { ctx.fillStyle = bg; ctx.fill(); }
      if (hasBorder) { ctx.lineWidth = bw; ctx.strokeStyle = bc; ctx.stroke(); }
    }
    function drawTextNode(node, el) {
      const text = node.textContent;
      if (!text || !text.trim()) return;
      const cs = getComputedStyle(el);
      const range = document.createRange(); range.selectNode(node);
      const rects = range.getClientRects(); if (!rects.length) return;
      const r = rects[0];
      ctx.fillStyle = cs.color;
      ctx.font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
      ctx.textBaseline = 'middle';
      ctx.fillText(text.trim(), r.left - hRect.left, r.top - hRect.top + r.height / 2 + 1);
    }
    function walk(el) {
      const cs = getComputedStyle(el);
      if (cs.display === 'none' || cs.visibility === 'hidden') return;
      const r = el.getBoundingClientRect();
      const x = r.left - hRect.left, y = r.top - hRect.top;
      const tag = el.tagName;
      if (tag === 'svg' || tag === 'SVG') {
        const s = new XMLSerializer().serializeToString(el);
        const url = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(s);
        iconJobs.push(new Promise((res) => { const img = new Image(); img.onload = () => { try { ctx.drawImage(img, x, y, r.width, r.height); } catch(e){} res(); }; img.onerror = () => res(); img.src = url; }));
        return;
      }
      if (tag === 'SELECT') {
        drawBg(el, x, y, r.width, r.height);
        const label = el.options[el.selectedIndex]?.text || el.value;
        ctx.save(); ctx.beginPath(); ctx.rect(x, y, r.width - 16, r.height); ctx.clip();
        ctx.fillStyle = cs.color; ctx.font = `${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`; ctx.textBaseline = 'middle';
        ctx.fillText(label, x + parseFloat(cs.paddingLeft), y + r.height / 2 + 1);
        ctx.restore();
        ctx.fillStyle = cs.color; ctx.font = '10px sans-serif'; ctx.fillText('▾', x + r.width - 13, y + r.height / 2 + 1);
        return;
      }
      if (tag === 'OPTION') return;
      drawBg(el, x, y, r.width, r.height);
      for (const child of el.childNodes) {
        if (child.nodeType === 3) drawTextNode(child, el);
        else if (child.nodeType === 1) walk(child);
      }
    }
    walk(header);
    await Promise.all(iconJobs);
    const overflowPx = header.scrollWidth - header.clientWidth;
    if (overflowPx > 0) {
      ctx.fillStyle = 'rgba(244,63,94,0.25)';
      ctx.fillRect(W - overflowPx, 0, overflowPx, H);
      ctx.strokeStyle = '#f43f5e'; ctx.lineWidth = 1;
      ctx.strokeRect(W - overflowPx + 0.5, 0.5, overflowPx - 1, H - 1);
    }
    canvas.toBlob((b) => {
      const a = document.createElement('a');
      a.href = URL.createObjectURL(b);
      a.download = `header-${W}px.png`;
      a.click();
      resolve({ w: W, h: H, pngBytes: b ? b.size : 0, overflowPx });
    }, 'image/png');
  });
}

